SELECT task.id, task.tenant_id, task.group_link_id, task.status, task.trigger_source, task.attempt_count, task.next_run_at, task.lease_until, task.execution_account_id, task.rerun_requested, task.last_started_at, task.last_success_at, task.last_error_code, task.last_error_message, task.created_at, task.updated_at, COALESCE( NULLIF(TRIM(current_group.group_jid), ''), CASE WHEN link.link_url LIKE 'wa://group/%' THEN SUBSTRING(link.link_url, CHAR_LENGTH('wa://group/') + 1) ELSE NULL END ) AS groupJid, CASE WHEN link.origin = 4 AND link.link_url LIKE 'wa://group/%' AND NULLIF(TRIM(COALESCE( current_invite.invite_code, input_invite.invite_code )), '') IS NULL THEN TRUE ELSE FALSE END AS inviteRequired FROM group_metadata_sync_task task INNER JOIN group_link link ON link.tenant_id = task.tenant_id AND link.id = task.group_link_id AND link.deleted_at IS NULL LEFT JOIN wa_group current_group ON current_group.tenant_id = link.tenant_id AND current_group.id = link.group_id LEFT JOIN wa_group_profile current_profile ON current_profile.tenant_id = current_group.tenant_id AND current_profile.group_id = current_group.id LEFT JOIN wa_group_invite current_invite ON current_invite.tenant_id = current_profile.tenant_id AND current_invite.id = current_profile.current_invite_id LEFT JOIN wa_group_invite input_invite ON input_invite.tenant_id = link.tenant_id AND input_invite.id = link.group_invite_id WHERE task.status IN
#{status}
AND ( (task.next_run_at IS NOT NULL AND task.next_run_at <= #{now}) OR (task.status = #{periodicStatus} AND task.next_run_at IS NULL) )
ORDER BY CASE WHEN task.last_success_at IS NULL THEN 0 WHEN task.status = 1 AND task.trigger_source IN (3, 4, 6) THEN 1 ELSE 2 END ASC, task.next_run_at ASC, task.id ASC LIMIT #{limit}

mapper.update:
UPDATE group_metadata_sync_task
SET status = #{row.status},
    attempt_count = #{row.attemptCount},
    lease_until = #{row.leaseUntil},
    execution_account_id = #{row.executionAccountId},
    rerun_requested = FALSE,
    last_started_at = #{row.lastStartedAt},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND tenant_id = #{row.tenantId}
  AND status IN

    #{status}

  AND (
    (next_run_at IS NOT NULL AND next_run_at <= #{row.updatedAt})
    OR (status = #{periodicStatus} AND next_run_at IS NULL)
  )
  AND (
    SELECT running_count FROM (
      SELECT COUNT(*) AS running_count
      FROM group_metadata_sync_task
      WHERE tenant_id = #{row.tenantId}
        AND status = #{runningStatus}
    ) tenant_running
  ) < #{tenantConcurrency}
  AND (
    SELECT running_count FROM (
      SELECT COUNT(*) AS running_count
      FROM group_metadata_sync_task
      WHERE execution_account_id = #{row.executionAccountId}
        AND status = #{runningStatus}
    ) account_running
  ) < #{accountConcurrency}

UPDATE group_metadata_sync_task
SET status = CASE
      WHEN #{row.status} = 4 AND rerun_requested = TRUE THEN 1
      ELSE #{row.status}
    END,
    attempt_count = CASE
      WHEN #{row.status} = 4 AND rerun_requested = TRUE THEN 0
      ELSE #{row.attemptCount}
    END,
    next_run_at = CASE
      WHEN #{row.status} = 4 AND rerun_requested = TRUE THEN #{row.updatedAt}
      ELSE #{row.nextRunAt}
    END,
    lease_until = NULL,
    execution_account_id = NULL,
    rerun_requested = FALSE,
    last_success_at = COALESCE(#{row.lastSuccessAt}, last_success_at),
    last_error_code = #{row.lastErrorCode},
    last_error_message = #{row.lastErrorMessage},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND tenant_id = #{row.tenantId}
  AND status = #{runningStatus}

UPDATE group_metadata_sync_task
SET status = #{row.status},
    next_run_at = NULL,
    lease_until = NULL,
    execution_account_id = NULL,
    rerun_requested = FALSE,
    last_error_code = #{row.lastErrorCode},
    last_error_message = #{row.lastErrorMessage},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND tenant_id = #{row.tenantId}
  AND status IN

    #{status}
